solution:
interface Produit {
  id: number;
  nom: string;
  prix: number;
  coutAchat: number;
}

const produits: Produit[] = [];

function creer(n: Omit<Produit, "id">): Produit {
  const p: Produit = { id: produits.length + 1, ...n };
  produits.push(p);
  return p;
}

function catalogue(): Readonly<Omit<Produit, "coutAchat">>[] {
  return produits.map(({ coutAchat, ...visible }) => visible);
}
